mapper.select:
SELECT SM.SALES_NO , SM.SALES_SEQ , SM.INVOICE_MONTH , SM.DIVISION_CODE , D.DIVISION_NAME , SM.CUSTOMER_CODE , C.CUSTOMER_NAME , SM.PRODUCT_CODE , IM.ITEM_NAME AS PRODUCT_NAME , IM.HS_CODE , SM.STATUS AS STATUS , GET_CODE_NAME(SM.STATUS, 'DS', SM.COMPANY_CODE, 'KOR') AS STATUS_NAME , GET_CODE_NAME(SM.PRODUCT_ASSETS_TYPE, 'AT', SM.COMPANY_CODE, 'KOR') AS PRODUCT_ASSETS_TYPE_NAME , SM.COO_CERTIFY_NO FROM (
SELECT G.COMPANY_CODE , G.INVOICE_MONTH , G.DIVISION_CODE , G.CUSTOMER_CODE , G.PRODUCT_CODE , G.STATUS , G.COO_CERTIFY_NO , G.PRODUCT_ASSETS_TYPE , G.QUANTITY , REP.SALES_NO , REP.SALES_SEQ FROM ( SELECT SM.COMPANY_CODE , SUBSTR(SM.INVOICE_DATE, 1, 6) AS INVOICE_MONTH , SD.DIVISION_CODE , SM.CUSTOMER_CODE , SD.PRODUCT_CODE , COALESCE(SUM(CASE WHEN SM.VIRTUAL_YN = 'Y' THEN SD.STATUS::INTEGER ELSE 0 END), 0)::VARCHAR AS STATUS , MAX(CASE WHEN SM.VIRTUAL_YN = 'Y' THEN SD.COO_CERTIFY_NO ELSE NULL END) AS COO_CERTIFY_NO , SD.PRODUCT_ASSETS_TYPE , SUM(SD.QUANTITY) AS QUANTITY FROM SALES_MST SM INNER JOIN SALES_DTL SD ON SM.COMPANY_CODE = SD.COMPANY_CODE AND SM.SALES_NO = SD.SALES_NO AND SM.DIVISION_CODE = SD.DIVISION_CODE INNER JOIN CUSTOMER C ON C.COMPANY_CODE = SD.COMPANY_CODE AND C.CUSTOMER_CODE = SD.DELIVERY_CUSTOMER_CODE LEFT JOIN CUSTOMER_MODEL CM ON CM.COMPANY_CODE = SD.COMPANY_CODE AND CM.DIVISION_CODE = SD.DIVISION_CODE AND CM.ITEM_CODE = SD.PRODUCT_CODE AND CM.CUSTOMER_CODE = SD.DELIVERY_CUSTOMER_CODE WHERE SM.COMPANY_CODE = #{company_code} AND SM.EXPORT_FLAG = 'D'
AND SM.INVOICE_DATE BETWEEN #{from_date} AND #{to_date}
GROUP BY SM.COMPANY_CODE , SUBSTR(SM.INVOICE_DATE, 1, 6) , SM.CUSTOMER_CODE , SD.DELIVERY_CUSTOMER_CODE , SD.DIVISION_CODE , SD.PRODUCT_CODE , SM.EXPORT_FLAG , SD.PROD_DIVISION_CODE , COALESCE(CM.CUSTOMER_ITEM_CODE, SD.CUSTOMER_ITEM_CODE) , SD.PRODUCT_ASSETS_TYPE ) G LEFT JOIN (
SELECT DISTINCT ON (SM4.COMPANY_CODE, SM4.CUSTOMER_CODE, SD4.DIVISION_CODE, SD4.PRODUCT_CODE, SUBSTR(SM4.INVOICE_DATE, 1, 6)) SM4.COMPANY_CODE , SM4.CUSTOMER_CODE , SD4.DIVISION_CODE , SD4.PRODUCT_CODE , SUBSTR(SM4.INVOICE_DATE, 1, 6) AS INVOICE_MONTH , SM4.SALES_NO , SD4.SALES_SEQ FROM SALES_MST SM4 INNER JOIN SALES_DTL SD4 ON SM4.COMPANY_CODE = SD4.COMPANY_CODE AND SM4.SALES_NO = SD4.SALES_NO AND SM4.DIVISION_CODE = SD4.DIVISION_CODE WHERE SM4.COMPANY_CODE = #{company_code} AND SM4.EXPORT_FLAG = 'D'
AND SM4.INVOICE_DATE BETWEEN #{from_date} AND #{to_date}
ORDER BY SM4.COMPANY_CODE, SM4.CUSTOMER_CODE, SD4.DIVISION_CODE, SD4.PRODUCT_CODE, SUBSTR(SM4.INVOICE_DATE, 1, 6) , SM4.VIRTUAL_YN DESC, SM4.SALES_NO, SD4.SALES_SEQ ) REP ON REP.COMPANY_CODE = G.COMPANY_CODE AND REP.CUSTOMER_CODE = G.CUSTOMER_CODE AND REP.DIVISION_CODE = G.DIVISION_CODE AND REP.PRODUCT_CODE = G.PRODUCT_CODE AND REP.INVOICE_MONTH = G.INVOICE_MONTH ) SM INNER JOIN ITEM_MST IM ON IM.COMPANY_CODE = SM.COMPANY_CODE AND IM.ITEM_CODE = SM.PRODUCT_CODE LEFT JOIN DIVISION D ON D.COMPANY_CODE = SM.COMPANY_CODE AND D.DIVISION_CODE = SM.DIVISION_CODE INNER JOIN CUSTOMER C ON C.COMPANY_CODE = SM.COMPANY_CODE AND C.CUSTOMER_CODE = SM.CUSTOMER_CODE WHERE 1=1 AND SM.QUANTITY > 0 -- 반품 제외
AND D.DIVISION_CODE = #{division_code}
AND (C.CUSTOMER_CODE ILIKE '%' || #{customer} || '%' OR C.CUSTOMER_NAME ILIKE '%' || #{customer} || '%' )
AND (SM.PRODUCT_CODE ILIKE '%' || #{product} || '%' OR IM.ITEM_NAME ILIKE '%' || #{product} || '%' )
AND SM.STATUS = #{status}
ORDER BY SM.INVOICE_MONTH, C.CUSTOMER_CODE, D.DIVISION_CODE, SM.PRODUCT_CODE, SM.SALES_NO, SM.SALES_SEQ

SELECT DISTINCT SM.SALES_NO , SD.SALES_SEQ , SD.PRODUCT_CODE , IM.ITEM_NAME AS PRODUCT_NAME , IM.HS_CODE , SD.QUANTITY , IM.UNIT , SD.UNIT_PRICE , SD.AMOUNT FROM (
SELECT #{d.sales_no} AS SALES_NO, #{d.division_code} AS DIVISION_CODE, #{d.sales_seq}::numeric AS SALES_SEQ
) KEYS INNER JOIN SALES_MST SM ON SM.COMPANY_CODE = #{company_code} AND SM.SALES_NO = KEYS.SALES_NO AND SM.DIVISION_CODE = KEYS.DIVISION_CODE INNER JOIN SALES_DTL SD ON SM.COMPANY_CODE = SD.COMPANY_CODE AND SM.SALES_NO = SD.SALES_NO AND SM.DIVISION_CODE = SD.DIVISION_CODE AND (KEYS.SALES_SEQ IS NULL OR SD.SALES_SEQ = KEYS.SALES_SEQ) INNER JOIN ITEM_MST IM ON IM.COMPANY_CODE = SD.COMPANY_CODE AND IM.ITEM_CODE = SD.PRODUCT_CODE

SELECT SM.SALES_NO , SM.INVOICE_DATE , D.DIVISION_CODE , D.DIVISION_NAME , C.CUSTOMER_CODE , C.CUSTOMER_NAME , SM.INVOICE_NO , SM.STATUS , GET_CODE_NAME(SM.STATUS, 'DS', SM.COMPANY_CODE, 'KOR') AS STATUS_NAME , GET_CODE_NAME(COALESCE(SM.ARRIVAL_NATION, FAN.NATION_CODE), 'NA', SM.COMPANY_CODE, 'KOR') AS EXPORT_NATION , FM.FTA_NAME /* , (SELECT COUNT(*) FROM FTA_APPLY_NATION FAN WHERE FAN.NATION_CODE = COALESCE(SM.ARRIVAL_NATION, C.NATION_CODE) AND FAN.EFFECT_DATE <= SM.INVOICE_DATE AND FM.FTA_CODE = FAN.FTA_CODE) AS FTA_CNT */ FROM ( SELECT SM.COMPANY_CODE , SM.SALES_NO , SM.DIVISION_CODE FROM SALES_MST SM INNER JOIN SALES_DTL SD ON SM.COMPANY_CODE = SD.COMPANY_CODE AND SM.SALES_NO = SD.SALES_NO AND SM.DIVISION_CODE = SD.DIVISION_CODE INNER JOIN ITEM_MST IM ON IM.COMPANY_CODE = SD.COMPANY_CODE AND IM.ITEM_CODE = SD.PRODUCT_CODE WHERE SM.COMPANY_CODE = #{company_code} AND SM.EXPORT_FLAG = 'E'
AND SM.INVOICE_DATE BETWEEN #{from_date} AND #{to_date}
AND (SD.PRODUCT_CODE ILIKE '%' || #{product} || '%' OR IM.ITEM_NAME ILIKE '%' || #{product} || '%' )
AND SM.STATUS = #{status}
GROUP BY SM.COMPANY_CODE, SM.SALES_NO, SM.DIVISION_CODE ) SALES INNER JOIN SALES_MST SM ON SM.COMPANY_CODE = SALES.COMPANY_CODE AND SM.SALES_NO = SALES.SALES_NO AND SM.DIVISION_CODE = SALES.DIVISION_CODE LEFT JOIN DIVISION D ON D.COMPANY_CODE = SM.COMPANY_CODE AND D.DIVISION_CODE = SM.DIVISION_CODE INNER JOIN CUSTOMER C ON C.COMPANY_CODE = SM.COMPANY_CODE AND C.CUSTOMER_CODE = SM.CUSTOMER_CODE LEFT JOIN FTA_MASTER FM ON SM.COMPANY_CODE = FM.COMPANY_CODE AND SM.TARGET_FTA_CODE = FM.FTA_CODE AND FM.DELETE_YN = 'N' AND FM.FTA_STATUS = '4' LEFT JOIN FTA_APPLY_NATION FAN ON FAN.NATION_CODE = C.NATION_CODE WHERE 1=1
AND D.DIVISION_CODE = #{division_code}
AND (C.CUSTOMER_CODE ILIKE '%' || #{customer} || '%' OR C.CUSTOMER_NAME ILIKE '%' || #{customer} || '%' )
ORDER BY SM.INVOICE_DATE, C.CUSTOMER_CODE, D.DIVISION_CODE

SELECT SM.INVOICE_DATE , SM.DIVISION_CODE , D.DIVISION_NAME , SM.EXPORT_FLAG , GET_CODE_NAME(SM.EXPORT_FLAG, 'EF', SM.COMPANY_CODE, 'KOR') AS EXPORT_FLAG_NAME , C.CUSTOMER_NAME , SD.PRODUCT_CODE , IM.ITEM_NAME AS PRODUCT_NAME , COALESCE(FM.HS_CODE, IM.HS_CODE) AS HS_CODE , F.FTA_NAME , FM.COMPANY_COO_YN AS ORIGIN_STATUS , SD.STATUS AS STATUS , GET_CODE_NAME(SD.STATUS, 'DS', SD.COMPANY_CODE, 'KOR') AS STATUS_NAME , SM.SALES_NO , SD.SALES_SEQ FROM SALES_MST SM INNER JOIN SALES_DTL SD ON SM.COMPANY_CODE = SD.COMPANY_CODE AND SM.SALES_NO = SD.SALES_NO AND SM.DIVISION_CODE = SD.DIVISION_CODE INNER JOIN FCR_MST FM ON FM.SALES_NO = SD.SALES_NO AND FM.SALES_SEQ = SD.SALES_SEQ AND FM.COMPANY_CODE = SD.COMPANY_CODE AND FM.DIVISION_CODE = SD.DIVISION_CODE LEFT JOIN FTA_MASTER F ON F.COMPANY_CODE = FM.COMPANY_CODE AND F.FTA_CODE = COALESCE(FM.FTA_CODE, SM.TARGET_FTA_CODE) INNER JOIN ITEM_MST IM ON IM.COMPANY_CODE = SD.COMPANY_CODE AND IM.ITEM_CODE = SD.PRODUCT_CODE LEFT JOIN CUSTOMER_MODEL CM ON CM.COMPANY_CODE = SD.COMPANY_CODE AND CM.ITEM_CODE = SD.PRODUCT_CODE AND CM.CUSTOMER_CODE = SD.DELIVERY_CUSTOMER_CODE AND CM.DIVISION_CODE = SD.PROD_DIVISION_CODE LEFT JOIN DIVISION D ON D.COMPANY_CODE = SM.COMPANY_CODE AND D.DIVISION_CODE = SM.DIVISION_CODE LEFT JOIN CUSTOMER C ON C.CUSTOMER_CODE = COALESCE(SD.DELIVERY_CUSTOMER_CODE, SM.CUSTOMER_CODE) AND C.COMPANY_CODE = SD.COMPANY_CODE WHERE SM.COMPANY_CODE = #{company_code} AND SM.COO_DATE IS NOT NULL AND ((SM.EXPORT_FLAG = 'D' AND SM.VIRTUAL_YN = 'Y') OR (SM.EXPORT_FLAG = 'E' AND SM.TARGET_FTA_CODE IS NOT NULL)) AND EXISTS ( SELECT 1 FROM FCR_DTL FD WHERE FD.COMPANY_CODE = FM.COMPANY_CODE AND FD.SALES_NO = FM.SALES_NO AND FD.SALES_SEQ = FM.SALES_SEQ AND FD.DIVISION_CODE = FM.DIVISION_CODE AND FD.FTA_CODE = FM.FTA_CODE )
AND SM.INVOICE_DATE BETWEEN #{from_date} AND #{to_date}
AND (SM.PRODUCT_CODE ILIKE '%' || #{product} || '%' OR IM.ITEM_NAME ILIKE '%' || #{product} || '%' )
AND D.DIVISION_CODE = #{division_code}
AND (C.CUSTOMER_CODE ILIKE '%' || #{customer} || '%' OR C.CUSTOMER_NAME ILIKE '%' || #{customer} || '%' )
AND SD.STATUS = #{status}
AND SM.EXPORT_FLAG = #{export_flag}
ORDER BY SM.INVOICE_DATE, C.CUSTOMER_CODE, D.DIVISION_CODE, SD.PRODUCT_CODE, F.FTA_NAME
